INSERT OR IGNORE INTO services (slug, name, tagline, summary, sticker, icon, tone, tags, card_cta, intro, visual, image, note, features, ideal_for, content, cta, show_on_home, sort, published) VALUES ('lead-generation', 'Lead Generation', 'Stop waiting for walk-ins. Get enquiries every single day.', 'New enquiries every day — from people who actually want to buy. Every lead tracked.', '+3.2x leads', '/assets/icons/lead-gen.svg', 'lime', '["Landing pages","Lead magnets","Google Sheets"]', '', 'A complete lead system for your business: a focused landing page, an offer people can’t refuse, visitors from ads or Google, and WhatsApp follow-up — so no enquiry slips away.', 'funnel', '', 'Every lead tracked!', '["High-converting landing page built around one offer","Lead magnets: free consult, price list, trial class","Every lead auto-saved to Google Sheets","Weekly report: leads, cost per lead, next steps"]', '["Coaching centres filling batches","Clinics wanting new patients","Any business with an empty calendar"]', '## How it works

1. **Pick one offer** — a free consultation, trial class or price list that your customers actually want.
2. **Build a focused landing page** — one page, one goal, with a big WhatsApp button.
3. **Send the right visitors** — from Facebook, Instagram and Google, only from your area.
4. **Track every lead** — each enquiry is saved to Google Sheets so nothing gets lost.
5. **Improve every week** — you get a simple report and we fix what isn''t working.', 'Get more leads for my business', 1, 1, 1);
INSERT OR IGNORE INTO services (slug, name, tagline, summary, sticker, icon, tone, tags, card_cta, intro, visual, image, note, features, ideal_for, content, cta, show_on_home, sort, published) VALUES ('whatsapp', 'WhatsApp Automation', 'Answer every customer in seconds — even at midnight.', '24/7 auto-replies, menus and bookings — never miss a customer again.', '0.5s reply', '', 'navy', '["Auto-reply","Bookings","Follow-ups"]', '', 'Our customers prefer WhatsApp over forms or email. Smart menus, instant replies and bookings on your WhatsApp Business number — leads keep coming in even while you sleep.', 'chat', '', 'Replies in 0.5 sec', '["Instant greeting with services, prices and timings","Slot booking and catalogue sharing","Automatic follow-ups for people who go quiet","Your team can take over any chat anytime"]', '["Businesses that miss calls","Owners answering the same questions daily","Anyone getting enquiries after hours"]', '## How it works

1. **We map your common questions** — prices, timings, location, booking.
2. **We set up smart menus and replies** on your WhatsApp Business number.
3. **Bookings and catalogues** are shared automatically, any time of day.
4. **Follow-ups go out on their own** to people who stopped replying.
5. **You stay in control** — jump into any chat whenever you want.', 'Automate my WhatsApp', 1, 2, 1);
INSERT OR IGNORE INTO services (slug, name, tagline, summary, sticker, icon, tone, tags, card_cta, intro, visual, image, note, features, ideal_for, content, cta, show_on_home, sort, published) VALUES ('local-business-promotion', 'Local Business Promotion', 'Get noticed in your own area — and bring nearby customers through your door.', 'Grow your local business visibility and reach more potential customers in your area through creative local marketing campaigns.', '📍 Get noticed nearby', '/assets/icons/local-promo.svg', 'white', '["Offers & discounts","Posters","Influencers","Social media","Local reach"]', 'Promote Your Business', 'We help local businesses get noticed in their own area through promotional campaigns, attractive posters, social media marketing, and local influencer collaborations. This is not just paid advertising — it''s everything that puts your offers in front of the people who live and shop near you.', 'promo', '', 'Your area, your customers', '["Local offer & discount announcements","Promotional posters & creative designs","Local influencer marketing & collaborations","Social media promotion","Local audience reach & brand awareness"]', '["Shops and restaurants launching an offer","New businesses that need to be known locally","Salons, gyms and clinics wanting more walk-ins"]', '## How it works

1. **Plan the campaign** — we pick the offer, the timing (festivals, weekends, launches) and the area you want to reach.
2. **Design the creatives** — eye-catching posters, banners and social posts that match your brand.
3. **Collaborate with local influencers** — we find creators your neighbourhood already follows and run the collaboration for you.
4. **Promote everywhere it matters** — your social pages, local groups, WhatsApp status and, when it helps, targeted ads.
5. **Measure the reach** — you see how many local people saw, shared and responded to the campaign.

## Why it works

People buy from businesses they see and trust nearby. A good offer, a good-looking poster and a recommendation from a familiar local face does more than a generic ad.', 'Promote Your Business', 1, 3, 1);
INSERT OR IGNORE INTO services (slug, name, tagline, summary, sticker, icon, tone, tags, card_cta, intro, visual, image, note, features, ideal_for, content, cta, show_on_home, sort, published) VALUES ('web-dev', 'Websites & Apps', 'A fast website that works like your best salesperson.', 'Opens in a blink on mobile, and takes visitors straight to a call or WhatsApp.', '<1.5s load', '/assets/icons/website-dev.svg', 'butter', '["Mobile-first","SEO ready","Booking forms"]', '', 'Clean, mobile-first websites and simple web apps — they load in 1.5 seconds, rank on Google, and guide every visitor towards a call or WhatsApp.', 'web', '', 'Loads in a flash', '["Custom design — no slow templates","1-tap WhatsApp & call buttons everywhere","SEO-ready structure and Google Maps","Booking forms, catalogues, dashboards"]', '["Businesses with no website yet","Slow or outdated WordPress sites","Owners who need a simple web app"]', '## How it works

1. **A short call** to understand your business and customers.
2. **Design and content** — we write the copy and design every page for mobile first.
3. **Build and launch** — fast, secure and connected to WhatsApp, Google Maps and your forms.
4. **Ongoing support** — price changes, new photos and offers, just send them on WhatsApp.', 'Get a website for my business', 1, 4, 1);
INSERT OR IGNORE INTO services (slug, name, tagline, summary, sticker, icon, tone, tags, card_cta, intro, visual, image, note, features, ideal_for, content, cta, show_on_home, sort, published) VALUES ('meta-ads', 'Meta Ads (FB & IG)', 'Ads that bring enquiries, not just likes.', 'Facebook and Instagram ads that reach customers near your shop.', '5–15 km radius', '/assets/icons/meta-ads.svg', 'white', '["Local targeting","Ad creatives","Pixel tracking"]', '', 'Campaigns targeting people around your pincode — eye-catching design and copy that bring them straight to your WhatsApp.', 'ad', '', 'Only nearby buyers', '["Hyper-local targeting within 5–15 km","Ad creatives, reels and copywriting","Meta Pixel & Conversions API tracking","Budgets that work from ₹200–₹400/day"]', '["Salons and spas filling weekdays","Restaurants promoting offers","New businesses that need awareness fast"]', '## How it works

1. **Set the area and audience** — only people within 5–15 km who are likely to buy.
2. **Create the ads** — images, reels and copy that make people tap “Send Message”.
3. **Track results properly** — Meta Pixel and Conversions API so you know what each enquiry costs.
4. **Optimise weekly** — we pause what doesn''t work and push what does.

Your ad budget is paid directly to Meta.', 'Run Meta Ads for my business', 0, 5, 1);
